R,C=17,19
g=[[0]*C for _ in range(R)]
pts=[(3,4),(8,11),(13,6)]
for r,c in pts:
    # upper frame
    for j in range(c-2,c+3):
        if 0<=r-2<R and 0<=j<C:g[r-2][j]=5
    # two sides and raised central stripe
    for i in (r-1,r,r+1):
        for j in (c-2,c+2):
            if 0<=i<R and 0<=j<C:g[i][j]=2
    if 0<=r-1<R:g[r-1][c]=5
    # base line across width, central opening in color 8
    if 0<=r+2<R:
        g[r+2]=[2]*C
        for j in range(c-1,c+2):
            if 0<=j<C:g[r+2][j]=8
print('\n'.join(' '.join(map(str,row)) for row in g))
